using static StrataLint.Scribe.DefinitionDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Topology;

internal sealed class JBAmbientSupportDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Ambient order domination by an idempotent forces support in its Peirce two-space on the original complete real six-law JB carrier.",
        H("Ambient idempotent support"),
        Blocks(
            Paragraph(Text("Let X be any complete real normed vector space, S its specified real bilinear product, and u its specified unit. Data(X,S,u) consists of symmetry, the unit law, the Jordan identity, product norm domination, the square norm identity and square monotonicity. Write K(y) for the existence of z in this same X with S(z,z)=y, and write U(r,y)=2 S(r,S(r,y))-S(S(r,r),y). The zero space and zero idempotent are included.")),
            Describe.Lean(DescribeId.Create("ambient-idempotent-support"),
                DeclarationHandle.Create("D5/S3/Topology/JBAmbientSupport.support_of_squares"),
                H("Domination forces support"), StatementSource.FromAuthor(F.Disp(Scope(
                    All("p", V("X"), All("x", V("X"), All("c", V("Reals"),
                    Imp(And(Idempotent, And(K(Add(CP, V("x"))), K(Sub(CP, V("x"))))),
                    Eq(P(V("p"), V("x")), V("x"))))))))), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Set q=u-p and g(t)=U(u+tq,cp+x), h(t)=U(u+tq,cp-x). The original quadratic positivity theorem makes g(t) and h(t) actual squares for every real t. Bilinear expansion gives g(t)+h(t)=2cp and g(t)-g(-t)=4t S(q,x). Square monotonicity gives norm(g(t))<=2 norm(cp), hence abs(t) norm(S(q,x))<=norm(cp) uniformly in t. If S(q,x) is nonzero, t=(norm(cp)+1)/norm(S(q,x)) contradicts this bound. Therefore S(q,x)=0 and S(p,x)=x. No sign restriction on c is needed for this implication.")))),
            Describe.Lean(DescribeId.Create("supported-ambient-bounds"),
                DeclarationHandle.Create("D5/S3/Topology/JBAmbientSupport.squares_of_supported"),
                H("The original norm bounds supported vectors"), StatementSource.FromAuthor(F.Disp(Scope(
                    All("p", V("X"), All("x", V("X"),
                    Imp(And(Idempotent, Eq(P(V("p"), V("x")), V("x"))),
                    And(K(Add(Scale(N(V("x")), V("p")), V("x"))),
                        K(Sub(Scale(N(V("x")), V("p")), V("x")))))))))), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("The original ambient center theorem makes norm(x)u+x and norm(x)u-x squares. Apply the original positive quadratic map U(p), which sends u to p and fixes x. Thus both norm(x)p+x and norm(x)p-x are actual ambient squares. Together with domination forcing support, this identifies the Peirce two-space with the vectors bounded above and below by a nonnegative scalar multiple of p. It does not assert equality with the corner's internal square cone.")))),
            Describe.Lean(DescribeId.Create("corner-square-bound"),
                DeclarationHandle.Create("D5/S3/Topology/JBAmbientSupport.corner_square_bound"),
                H("The square bound in the same ambient cone"), StatementSource.FromAuthor(F.Disp(Scope(
                    All("p", V("X"), All("a", V("X"),
                    Imp(And(Idempotent, Eq(P(V("p"), V("a")), V("a"))),
                    K(Sub(Scale(Call("square", N(V("a"))), V("p")), P(V("a"), V("a")))))))))),
                AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Specializing the existing polarized Jordan identity to p,p,a,a gives S(p,S(a,a))=S(a,a). The preceding supported-vector bound applied to S(a,a), and the original square norm identity, give norm(a)^2 p-S(a,a) as an actual square. Its root is required only in X. These consequences use the original product and norm and impose no square-root closure on a dense original subalgebra.")))),
            Paragraph(Text("Application to the original dense-domain corner. Fix the original real normed domain E0, its faithful linear isometry i:E0->X, its symmetric bilinear product J, original unit u0, exact cone C, and the original label-indexed real linear evaluations alpha in P. Assume i(u0)=u, i(J(a,b))=S(i(a),i(b)), range(i) is dense, and a belongs to C exactly when i(a) is an ambient square, equivalently when every original alpha(a) is nonnegative. Retain original separation and every original mass alpha(u0). Fix an actual p0 in E0 with J(p0,p0)=p0 and put p=i(p0), E=range(i). Transport an evaluation to E by phi_alpha(i(a))=alpha(a), using i's equivalence with its range. All products, units, norms and evaluation values below use these specified maps. This is an application of existing declarations and pinned upstream results; it introduces no additional mathematical declaration.")),
            Paragraph(Text("The actual completed corner is the real submodule Xp=ker(S(p)-id), with the inherited norm, and Ep=E intersect Xp. It corresponds under i exactly to "),
                Ref("D5/S3/Quantum/Algebra/PBOriginalReadoutRealization.originalCorner"),
                Text(" with parameters (i.toLinearMap,S,p0). Write Lp=S(p) and Up=2 Lp^2-Lp, exactly "),
                Ref("D5/S3/Topology/JBPositiveShift.quadratic"), Text(" at p. Specialize "),
                Ref("D5/S3/Topology/JBAlgebra.polarized"),
                Text(" to p,p,a,b with S(p,a)=a: bilinear expansion gives S(p,S(a,b))=S(a,S(p,b)). Thus Xp and Ep are closed under the original product; their unit is p. The same identity at p,p,x,p gives Lp(Up(x))=Up(x). If Lp(x)=x, then Up(x)=x. Since Up is a polynomial in multiplication by the original p, Up(E) is contained in E. Consequently range(Up)=Xp and Up(E)=Ep, with both inclusions and the inverse on Ep supplied by the identity restriction. The six fields of JBAlgebra.Data restrict to Xp with S replaced by its restriction and u replaced by p; no new norm or product is chosen.")),
            Paragraph(Text("The map Lp is the existing continuous map "), Ref("D5/S3/Topology/JBAlgebra.lmul"),
                Text(" at (A,p). Its difference from the identity has closed kernel, so IsClosed.completeSpace_coe makes Xp complete. The polynomial Up is continuous. Applying mem_closure_image to Up and dense E, and then using Up(E)=Ep and Up(x)=x on Xp, gives closure(Ep)=Xp. Conversely Ep is contained in the closed kernel Xp. Equivalently denseRange_inclusion_iff makes the original inclusion j:Ep->Xp have dense range. This proves the full original-domain/completion correspondence without extending the unknown response to any completed input.")),
            Paragraph(Text("For clarity, the positive norming functional used here is the existing generated-algebra application in the JBComplexification Scribe. Its concrete suppliers are JBComplexification.Generated, generatedCommRing, generatedSquareLaws, generatedCompleteSpace, real_gelfand_norm, real_character_value and real_character_scalar, the pinned gelfandStarTransform, compactness of the character space, and exists_extension_norm_eq. For each nonzero z, take R=Generated(A,z), select a character attaining the sup norm of the Gelfand image of z, and extend its real restriction from R to X with unchanged operator norm. This gives beta(u)=1, norm(beta)<=1 and abs(beta(z))=norm(z). For every ambient square y, "),
                Ref("D5/S3/Topology/JBComplexification.square_iff_center"),
                Text(" gives norm(y-norm(y)u)<=norm(y); contractivity therefore gives abs(beta(y)-norm(y))<=norm(y), proving beta(y)>=0. These auxiliary mathematical functionals are used only to establish the norm and cone identities; they do not enlarge the original preparation-label family. If the tested vector is zero, its norm bound is immediate and no norming functional is selected.")),
            Paragraph(Text("Here is the supported-root application using those same suppliers. Let y be an ambient square with S(p,y)=y and t=norm(y). The frozen squares_of_supported at (A,p,y) gives t p+y and t p-y as ambient squares. For every positive norming beta, positivity of y and t p-y gives 0<=beta(y)<=t beta(p); the idempotents p and u-p are squares, so 0<=beta(p)<=1. Hence abs(beta(y-t p))<=t. Selecting beta norming y-t p proves norm(y-t p)<=t, with the zero-vector case handled directly. Apply "),
                Ref("D5/S3/Topology/JBComplexification.square_of_ambient_center"),
                Text(" to the inherited complete JB data on Xp, the element y in Xp and radius t. The resulting root r lies in that very Xp and S(r,r)=y. The converse is the same root viewed in X. Thus the internal square cone of the actual ker corner equals its ambient-square restriction, not merely one inclusion. This route uses the original public center theorem with X replaced by Xp, S by the restricted product and u by p; it requires no private generated-algebra helper or assertion about the Peirce components of an arbitrary root.")),
            Paragraph(Text("Put Kp=Xp intersect the ambient square cone and Cp=Ep intersect Kp. The latter corresponds exactly to C restricted to originalCorner. The square cone is closed by square_iff_center and continuity of y -> norm(y-norm(y)u)-norm(y), so Kp is closed. Given y in Kp, take the supported root r just obtained, approximate r by r_n in Ep using its dense inclusion, and square: S(r_n,r_n) lies in Cp and converges to y by the original product norm bound. This proves closure(Cp)=Kp. Equally, the original positive-shift approximants in formula 119.11 are legitimate: if a_n in Ep tends to y with norm(a_n-y)<=epsilon_n decreasing to zero, positivity and the norming-functional bounds give every positive beta on Xp the inequality beta(a_n+epsilon_n p)>=0. The same center-ball argument then puts a_n+epsilon_n p in Kp, hence in Cp. No square root in incomplete Ep is asserted.")),
            Paragraph(Text("The original norm is exactly the order-unit gauge. For x in Xp, squares_of_supported attains the nonnegative radius norm(x): norm(x)p+x and norm(x)p-x are in Kp. Conversely, if r>=0 and rp+x and rp-x are squares, a positive functional beta norming nonzero x gives abs(beta(x))<=r beta(p)<=r, hence norm(x)<=r. For x=0 the conclusion is immediate. Thus norm(x) is the least element of the set of admissible radii, and IsLeast.csInf_eq identifies its infimum with norm(x), including the zero corner. For x in Ep both bounding vectors are original, so the identical set is {r>=0:rp+x and rp-x belong to Cp}. The inherited unit is p, and its square is p; the original real square and real-addition identities restrict with the unchanged bilinear S.")),
            Paragraph(Text("Every original small window is preserved. Fix the original 0<theta<=1 and e in Ep with e and theta p-e in Cp. In the complete corner's actual generated algebra R=Generated(Ap,e), square_iff_center, real_gelfand_norm and the real-character identities imply that every character value v of e is real and 0<=v<=theta. Therefore v-v^2>=0. Apply the pinned inverse gelfandStarTransform to the continuous real function sqrt(v-v^2). Its inverse is selfadjoint, and JBComplexification.realEquiv identifies it with a real r in R; the square of r is e-e^2, by pointwise multiplication and injectivity of the transform. This is the existing real square-root construction on the generated complex C* algebra. Thus e-e^2 belongs to Kp and, since e is original and E is product-closed, to Cp. The same argument includes p=0 and the zero carrier. It does not change theta or assume completeness of E.")),
            Paragraph(Text("All original evaluations restrict separately, indexed by the unchanged P: phi_alpha^p=phi_alpha|Ep. Coincident restrictions are not identified, and zero restrictions remain. Original cone detection and separation apply to each original corner element and difference, so the restricted family detects Cp and separates Ep. Set m_alpha^p=phi_alpha(p)=alpha(p0), retaining m_alpha=alpha(u0). Since p and u-p are squares in E, 0<=m_alpha^p<=m_alpha. Applying phi_alpha to the two supported bounds gives abs(phi_alpha^p(a))<=m_alpha^p norm(a). In particular m_alpha^p=0 forces that entire restriction to vanish, even if m_alpha>0. Unequal, zero and subnormalized masses are preserved without division by either mass.")),
            Paragraph(Text("For each fixed original alpha apply LinearMap.extendOfNorm to f=phi_alpha^p:Ep->R and j:Ep->Xp, with dense range as above and bound C=m_alpha^p. LinearMap.extendOfNorm_eq preserves every original corner reading and the value m_alpha^p at p. LinearMap.norm_extendOfNorm_apply_le gives abs(Psi_alpha(x))<=m_alpha^p norm(x) for all x in Xp. Since Cp is dense in Kp and {x:0<=Psi_alpha(x)} is closed, the extension is positive on the exact internal square cone. LinearMap.extendOfNorm_unique proves uniqueness among continuous linear maps agreeing on Ep. If m_alpha^p=0 its norm bound makes Psi_alpha identically zero. This proves positive continuous extension, its quantitative bound and uniqueness for every original label, with the original mass. It neither asserts that these labels exhaust all mathematical corner states nor supplies any preparation.")),
            Paragraph(Text("For the actual response retain the original total function D:E0->E0->E0, with no linearity, continuity or completed-domain extension. Assume the same original directed P2 tables and the exact original cone/readout hypotheses. Apply "),
                Ref("D5/S3/Quantum/Algebra/PBIdempotentSupport.original_p2_support"),
                Text(" with its arguments (S,u,A,J,D,C,i,evaluation,hj,hcone,hdetect,hP2,p0,hp,a,b,ha,hb). Its third conclusion puts this very D(a,b) in originalCorner(i,S,p0); its first two give the original quantitative cone bounds. In particular Dp=D restricted to originalCorner squared is a total map to that same originalCorner. Both directed entries are still alpha(J(a,b))-i alpha(D(a,b)) and alpha(J(b,a))-i alpha(D(b,a)), with the same original labels and masses. This is pointwise support for one common output, not a separately selected response for each label.")),
            Paragraph(Text("For the actual phase-balance consumer take any original a,b,c in the corner. Product closure and the same-D support give nu=D(a,b)-J(a,c) and omega=J(a,b)+D(a,c) in the corner. Thus r+=b+nu, r-=b-nu, s+=c+omega and s-=c-omega are original corner inputs. Applying the support result again to (r+,s+) and (r-,s-) keeps both outer D outputs there. Their squares, sum and twice D are original corner elements too. For each unchanged alpha define Q_alpha(r,s)=alpha(J(r,r)+J(s,s)+2D(r,s)). Every term and both sides of Q_alpha(r+,s+)=Q_alpha(r-,s-) are precisely the original calls and readings of formula 120.2. Consequently a supplied original PB equality restricts verbatim at every original corner triple and every original label. No expansion of D on a sum, separately chosen output, normalization or global NN/J premise enters this inheritance.")),
            Paragraph(Text("For each original a in the corner, La preserves it and Ka^p=(La|Ep)^2-L_(a^2)|Ep is exactly the restriction of the original Ka. If NN is additionally supplied on the original whole domain, its inner D(a,b) and outer D(a,D(a,b)) are both legitimate original corner calls, so that same identity restricts. If full J is supplied, each of D(b,c), D(c,a), D(a,b) and every corresponding outer call stays in the corner, so the full three-term identity restricts. Neither NN nor J is deduced from the static interface or from merely having restricted PB. The inherited interface makes the actual PB inputs available for the spin and finite-model consumers; their classifications in 121 and 122 remain separate obligations. Finite-dimensional identification E=X, when explicitly assumed and justified, permits actual central units and rank-two idempotents as inputs, but is not a hypothesis of this general corner application.")),
            Paragraph(Text("If Xp is the scalar line Rp, write original corner inputs as a=sp and b=tp. Bilinearity and p^2=p make the original determinant budget alpha(a^2)alpha(b^2)-alpha(J(a,b))^2 equal to (s^2 alpha(p))(t^2 alpha(p))-(st alpha(p))^2=0 for each original label, without assuming alpha(p)>0. PBOriginalReadoutRealization.positive_table_transfer therefore gives alpha(D(a,b))^2<=0; original separation gives Dp(a,b)=0. For p=0 the corner is zero, all original restrictions are retained as zero labels and the response is the unique zero map. These conclusions use the same original P2 and do not require new mathematical states as physical labels.")),
            Paragraph(Text("This application supplies the complete original restriction interface of formulas 119.11-119.12 and the actual nested inputs of 120.2 by reuse. It preserves the original Omega and all source/native obligations of 119.1 and 119.8. A mathematical ker corner, projection polynomial, positive functional, spectrum or classification coordinate supplies no actual compression instrument, legal history, preparation menu, source realization, clock, energy or common hbar. General same-D additivity, homogeneity, continuity, compression compatibility, mixed-block decomposition, cross-corner orientation and global R remain unpaid. No 121/122 classification, global response theorem, physical realization, new audit registration or literature novelty is asserted.")))));

    private static Formula V(string s) => F.Id(s);
    private static Formula Call(string s, params Formula[] args) => new Formula.Apply(V(s), [.. args]);
    private static Formula All(string s, Formula type, Formula body) => new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(s), type, body);
    private static Formula Imp(Formula x, Formula y) => new Formula.Logic(x, FormulaLogicOperator.Implies, y);
    private static Formula And(Formula x, Formula y) => new Formula.Logic(x, FormulaLogicOperator.And, y);
    private static Formula Eq(Formula x, Formula y) => new Formula.Relation(x, FormulaRelationOperator.Equal, y);
    private static Formula P(Formula x, Formula y) => Call("S", x, y);
    private static Formula K(Formula x) => Call("K", x);
    private static Formula N(Formula x) => Call("norm", x);
    private static Formula Add(Formula x, Formula y) => new Formula.Binary(x, FormulaBinaryOperator.Add, y);
    private static Formula Sub(Formula x, Formula y) => new Formula.Binary(x, FormulaBinaryOperator.Subtract, y);
    private static Formula Scale(Formula x, Formula y) => Call("scale", x, y);
    private static Formula CP => Scale(V("c"), V("p"));
    private static Formula Idempotent => Eq(P(V("p"), V("p")), V("p"));
    private static Formula Scope(Formula body) => All("X", V("CompleteRealNormedSpaces"),
        All("S", Call("RealBilinearMaps", V("X")), All("u", V("X"),
        Imp(Call("Data", V("X"), V("S"), V("u")), body))));
}
